={{ (() => {
  const body = $('Records Webhook').first().json.body;
  const MAX_RECORDS = 100, MAX_CHARS = 10000;
  const errors = {};
  let input = [];
  if (body && Array.isArray(body.records)) input = body.records;
  else if (body && typeof body === 'object' && !Array.isArray(body) && Object.keys(body).length) input = [body];
  if (input.length === 0) errors.records = 'Send {"records": [...]} with at least one record';
  if (input.length > MAX_RECORDS) errors.records = 'Max ' + MAX_RECORDS + ' records per request (got ' + input.length + ')';

  const batchId = 'REV-' + $now.toFormat('yyyyMMdd-HHmmss') + '-' + $execution.id;
  const s = v => (v === undefined || v === null) ? '' : String(v).trim();
  const records = [];
  input.slice(0, MAX_RECORDS).forEach((r, i) => {
    const at = 'records[' + i + ']';
    if (!r || typeof r !== 'object' || Array.isArray(r)) { errors[at] = 'Must be an object'; return; }
    const content = r.content ?? r.text ?? r.description ?? r.message;
    if (typeof content !== 'string' || !content.trim()) { errors[at + '.content'] = 'Required non-empty string'; return; }
    if (content.length > MAX_CHARS) { errors[at + '.content'] = 'Max ' + MAX_CHARS + ' characters'; return; }
    const amount = typeof r.amount === 'string' && r.amount.trim() !== '' ? Number(r.amount) : r.amount;
    records.push({
      batch_id: batchId,
      record_id: s(r.id) || (batchId + '-' + (i + 1)),
      title: s(r.title ?? r.subject).slice(0, 200),
      content: content.trim(),
      customer_email: s(r.customer_email ?? r.email).toLowerCase(),
      amount: typeof amount === 'number' && Number.isFinite(amount) ? amount : null,
      currency: s(r.currency),
      source: s(r.source ?? body.source) || 'api',
      created_at: s(r.created_at),
      metadata: (r.metadata && typeof r.metadata === 'object') ? r.metadata : {}
    });
  });
  const valid = Object.keys(errors).length === 0;
  return { valid, errors, batch_id: batchId, count: records.length, records: valid ? records : [] };
})() }}

={{ (() => {
  const cfg = $('Config').first().json;
  const text = (String($json.title ?? '') + ' ' + String($json.content ?? '')).toLowerCase();
  const keywords = String(cfg.risk_keywords ?? '').split(',').map(k => k.trim().toLowerCase()).filter(Boolean);
  const hits = keywords.filter(k => text.includes(k));
  const flags = [];
  let force = false;
  if (hits.length) { flags.push('risk keywords: ' + hits.join(', ')); force = true; }
  if (typeof $json.amount === 'number' && $json.amount >= cfg.amount_threshold) {
    flags.push('amount ' + $json.amount + ' >= ' + cfg.amount_threshold); force = true;
  }
  if (!$json.customer_email) flags.push('no customer email');
  return { flags, force_review: force };
})() }}

parameters.text:
=Review this refund request and decide whether a person must approve it.

Request (JSON):
{{ JSON.stringify($json.record, null, 2) }}

Hard-rule flags computed by code (facts): {{ $json.rules.flags.length ? $json.rules.flags.join('; ') : 'none' }}

assignments.value:
={{ (() => {
  const rules = $('Apply Hard Rules').item.json.rules;
  const cfg = $('Config').first().json;
  const o = $json.output;
  const aiOk = !!o && typeof o.needs_human_review === 'boolean';
  let needs, by, reason;
  if (!aiOk) {
    needs = true; by = 'fail_safe';
    reason = 'Automated review failed: ' + String($json.error ?? 'no structured output').slice(0, 200);
  } else if (rules.force_review) {
    needs = true; by = 'hard_rule';
    reason = rules.flags.join('; ') + ' | AI: ' + o.reason;
  } else if (o.needs_human_review) {
    needs = true; by = 'ai'; reason = o.reason;
  } else if (o.confidence < cfg.confidence_threshold) {
    needs = true; by = 'low_confidence';
    reason = 'AI suggested auto-clear with low confidence (' + o.confidence + ' < ' + cfg.confidence_threshold + '): ' + o.reason;
  } else {
    needs = false; by = 'ai'; reason = o.reason;
  }
  const basePriority = aiOk ? o.priority : 'high';
  return {
    needs_human_review: needs,
    decided_by: by,
    reason: reason.slice(0, 500),
    priority: needs && basePriority === 'low' ? 'medium' : basePriority,
    category: aiOk ? o.category : 'unknown',
    confidence: aiOk ? o.confidence : null,
    suggested_action: aiOk ? String(o.suggested_action).slice(0, 200) : 'Review manually: the automated review failed.',
    ai_status: aiOk ? 'OK' : 'FAILED'
  };
})() }}

={{ (() => {
  const f = $('Finalize Decision').item.json;
  const r = f.record, d = f.decision;
  const safe = (v) => String(v ?? '').replace(/</g, '‹').replace(/>/g, '›');
  const amount = r.amount !== null && r.amount !== undefined ? r.amount + (r.currency ? ' ' + safe(r.currency) : '') : 'not given';
  const excerpt = safe(String(r.content || '').replace(/\s+/g, ' ').slice(0, 500));
  return '*Refund request needs a decision* (' + d.priority + ', ' + d.category + ')\n' +
    '*Customer:* ' + safe(r.customer_email || 'unknown') + '   *Amount:* ' + amount + '\n' +
    '*Title:* ' + safe(r.title || '-') + '\n' +
    '*Why:* ' + safe(d.reason) + '\n' +
    '*Suggested:* ' + safe(d.suggested_action) + '\n' +
    '*Decided by:* ' + d.decided_by + (d.confidence !== null && d.confidence !== undefined ? ' (confidence ' + d.confidence + ')' : '') + (f.rules.flags.length ? '   *Flags:* ' + safe(f.rules.flags.join('; ')) : '') + '\n' +
    '“' + excerpt + (String(r.content || '').length > 500 ? '…' : '') + '”\n' +
    'Review ID: ' + safe(f.review_id);
})() }}

parameters.errorMessage:
={{ (() => {
  const q = $('When Approval Requested').first().json;
  return '[CRITICAL] Refund request ' + q.review_id + ' needs a person, but Slack refused the approval message 3 times (the API error is on the Ask Approver in Slack node of this execution). ' +
    'Customer ' + (q.record?.customer_email || 'unknown') + ', amount ' + (q.record?.amount ?? 'n/a') + ' ' + (q.record?.currency || '') + '. Reason: ' + q.decision?.reason + '. Decide manually and update the Review Log.';
})() }}

